import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { svg } from './svg.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Subsetted WOFF2 copies of the files in /fonts, generated by scripts/build-fonts.js.
// Cards embed them because an SVG shown as an image can't load external fonts.
const fonts = JSON.parse(fs.readFileSync(path.join(__dirname, '../assets/fontsBase64.json'), 'utf8'));

const fontFace = (family, { mime, format, data }) => svg`
        @font-face {
          font-family: '${family}';
          src: url('data:${mime};base64,${data}') format('${format}');
        }`;

/** @font-face rules for the card fonts, to place inside a card's <style> element. */
export function fontFaces() {
  return [
    fontFace('Rajdhani', fonts['Rajdhani-Regular']),
    fontFace('ChakraPetch', fonts['ChakraPetch-Regular']),
    fontFace('LibreBarcode128', fonts['LibreBarcode128-Regular']),
  ];
}
